export class MotionPerformanceProbe extends Component {
  target: TheatreGame | null = null;
  private previous = 0;
  private started = 0;
  private idleDone = false;
  private endAt = 0;
  private windowStarted = 0;
  private mode = '';
  private sequence = 0;
  private observedStarts = 0;
  private initialGestures: GestureCounters | null = null;
  private maxDrawCalls = 0;
  private samples: number[] = [];
  private initial: Counters | null = null;

  private begin(mode: string, now: number): void {
    this.mode = mode;
    this.windowStarted = now;
    this.endAt = now + 6000;
    this.initialGestures = this.target ? { ...this.target.getGestureDiagnostics() } : null;
    this.maxDrawCalls = 0;
    this.samples.length = 0;
    this.initial = this.target?.getPaperPerformanceStats() ?? null;
  }

  update(): void {
    const now = game.frameStartTime;
    if (!this.started) this.started = now;
    const interval = this.previous ? now - this.previous : 0;
    this.previous = now;
    // Observe production gesture counters without installing a full-screen UI
    // listener, which would alter Cocos UI event claiming and the measured flow.
    const gestures = this.target?.getGestureDiagnostics();
    if (gestures && gestures.starts !== this.observedStarts) {
      if (!this.endAt) this.begin('interaction', now);
      this.observedStarts = gestures.starts;
    }
    if (!this.endAt && !this.idleDone && now - this.started > 8000) {
      this.idleDone = true;
      this.begin('idle', now);
    }
    if (!this.endAt) return;
    // Raw wall-clock intervals include stalls; don't substitute clamped deltaTime.
    if (interval > 0) this.samples.push(interval);
    this.maxDrawCalls = Math.max(this.maxDrawCalls, director.root?.device.numDrawCalls ?? 0);
    if (now < this.endAt) return;
    const sorted = [...this.samples].sort((a, b) => a - b);
    const percentile = (p: number) => sorted[Math.min(sorted.length - 1, Math.floor(sorted.length * p))] ?? 0;
    const round = (n: number) => Math.round(n * 100) / 100;
    const final = this.target?.getPaperPerformanceStats() ?? null;
    const difference: Record<string, number> = {};
    if (this.initial && final) for (const key of Object.keys(final) as (keyof Counters)[]) difference[key] = final[key] - this.initial[key];
    const memory = director.root?.device.memoryStatus;
    console.log('[StickerPerf] ' + JSON.stringify({
