import { Rect, Size, SpriteFrame, Vec2 } from 'cc';

/**
 * Restore transparent padding on a standalone PNG's imported SpriteFrame.
 * The caller keeps the loaded source frame referenced while owning the derived frame.
 * This cannot undo atlas packing, texture resizing, rotation or physically cropped PNGs.
 */
export function completeSourceFrame(source: SpriteFrame, file: string): SpriteFrame {
  const texture = source.texture;
  const { width, height } = source.originalSize;
  if (!texture || source.rotated || source.atlasUuid || !Number.isInteger(width) || !Number.isInteger(height)
    || width <= 0 || height <= 0 || texture.width !== width || texture.height !== height) {
    throw new Error(`贴纸纹理必须保留完整原生 PNG 尺寸并关闭图集旋转/缩放：${file}`);
  }
  source.packable = false;
  if (source.rect.x === 0 && source.rect.y === 0 && source.rect.width === width
    && source.rect.height === height && source.offset.x === 0 && source.offset.y === 0) return source;
  const frame = new SpriteFrame();
  frame.texture = texture;
  frame.rect = new Rect(0, 0, width, height);
  frame.originalSize = new Size(width, height);
  frame.offset = new Vec2(0, 0);
  frame.packable = false;
  return frame;
}

