    if (!artwork || typeof artwork !== 'object') throw new Error('贴纸资源需要有效的 resources 路径');
    const record = artwork as { file?: unknown; assetKey?: unknown };
    const value = typeof record.assetKey === 'string' ? record.assetKey : record.file;
